/* HealthGuide visual and interaction reference. Mock-only, no network calls or storage. */
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const B=(text,action,style='')=>`<button class="btn ${style}" data-action="${action}">${text}</button>`;
const L=(text,id,style='')=>`<a class="${style}" href="#${route(id)}">${text}</a>`;
const badge=(text,type='')=>`<span class="badge ${type}"><span class="dot"></span>${text}</span>`;
const notice=(text,type='')=>`<div class="notice ${type}" role="status">${text}</div>`;
const feature=(mark,title,body)=>`<div class="feature"><span class="icon">${mark}</span><div><h3>${title}</h3><p class="small">${body}</p></div></div>`;
const field=(label,id,value='',type='text',hint='')=>`<label class="field">${label}<input id="${id}" type="${type}" value="${E(value)}">${hint?`<span class="hint">${hint}</span>`:''}</label>`;
const sel=(label,id,opts,val)=>`<label class="field">${label}<select id="${id}">${opts.map(o=>`<option ${o===val?'selected':''}>${E(o)}</option>`).join('')}</select></label>`;
const datum=(k,v)=>`<div class="datum"><span class="muted">${k}</span><b>${v}</b></div>`;
const SCENARIOS=[{id:'routine',title:'Find the right clinician',tag:'Full journey',desc:'Jordan explores recurring headaches and a suitable primary care visit.',concern:'I have recurring headaches after long workdays. I would like to understand the next step.',result:'A primary care conversation',tone:'blue'}, {id:'selfcare',title:'Explore self-care guidance',tag:'Shorter intake',desc:'A fictional mild concern demonstrates a shorter path with escalation advice.',concern:'I want to explore the mild-concern example and understand the self-care screen.',result:'Understand the self-care pathway',tone:''}, {id:'urgent',title:'Urgent interruption',tag:'Safety branch',desc:'A preset urgent answer interrupts questions and removes routine recommendations.',concern:'Load the fictional urgent-symptom scenario.',result:'Urgent action',tone:'red'}, {id:'unsupported',title:'Outside the demo scope',tag:'Scope branch',desc:'See how the experience explains a concern it cannot assess.',concern:'Load an unsupported demo concern.',result:'Another path is needed',tone:'amber'}, {id:'nomatch',title:'No matching doctors',tag:'Recovery path',desc:'Required insurance excludes every provider. Change filters explicitly.',concern:'I want to explore primary care with strict insurance preferences.',result:'A primary care conversation',tone:'blue'}, {id:'failure',title:'Guidance unavailable',tag:'Retry path',desc:'Simulate a generation failure, retain answers and recover with Retry.',concern:'I want to explore the service-failure demonstration.',result:'A primary care conversation',tone:'amber'}];
const PROVIDERS=[{id:'p01',name:'Dr. Maya Chen',initials:'MC',specialty:'Family medicine',practice:'Northlake Demo Clinic',distance:2.4,plan:'Demo Health PPO',tele:true,lang:'English',why:'Primary care fit · preferred plan · nearby'},{id:'p02',name:'Dr. Alex Rivera',initials:'AR',specialty:'Internal medicine',practice:'Riverside Demo Medical',distance:4.8,plan:'Demo Health PPO',tele:true,lang:'English / Spanish',why:'Primary care fit · preferred plan · telehealth'},{id:'p03',name:'Dr. Sam Patel',initials:'SP',specialty:'Family medicine',practice:'Oak Grove Demo Practice',distance:7.2,plan:null,tele:false,lang:'English',why:'Primary care fit · nearby; plan unknown'}];
const QUESTIONS=[{text:'When did this concern begin?',type:'single',choices:['Within the last week','One to four weeks ago','More than a month ago','Not sure'],why:'Timing changes which context the next question explores.'},{text:'Has the pattern changed?',type:'single',choices:['Improving','About the same','Worsening','Not sure'],why:'A changing pattern may need a different next step.'},{text:'How much does it affect your day?',type:'scale',why:'Impact helps prioritize the conversation.'},{text:'Which details apply to this example?',type:'multi',choices:['After long screen sessions','After missed meals','During physical activity','No pattern noticed'],why:'Selected context shapes the next fictional question.'},{text:'What have you already tried?',type:'text',why:'Earlier attempts help avoid repetitive suggestions.'},{text:'How long does each episode last?',type:'single',choices:['Less than an hour','One to four hours','More than four hours','Not sure'],why:'Duration adds context for the visit summary.'},{text:'Is there anything else to mention?',type:'text',why:'Your own words can capture context that a checklist misses.'},{text:'Would you like to discuss this with a clinician?',type:'single',choices:['Yes','I would like to understand my options','Not sure'],why:'This records your preference without changing urgency.'},{text:'What matters most for the next step?',type:'single',choices:['Understanding my concern','Finding the right clinician','Preparing for a visit'],why:'Your goal helps organize the guidance page.'},{text:'Are the details in this example complete?',type:'single',choices:['Yes, ready to review','Some details are unknown'],why:'Unknown details remain visible in the result.'}];
function fresh(){return {scenario:'routine',consent:false,mode:'guest',caseId:'demo-001',provider:'p01',profile:{age:'38',medications:'Not reported',allergies:'Unknown'},concern:SCENARIOS[0].concern,answers:[],question:0,record:false,fact:'pending',factText:'No medications listed in sample record',reviewed:false,guidance:false,generating:false,failed:false,retried:false,revision:1,criteria:{city:'Dallas, TX',radius:'25 miles',plan:'Demo Health PPO',required:false,visit:'Any visit type',language:'Any language'},history:[{id:'saved-001',title:'Routine care example',date:'Sample consultation',scenario:'routine'}],retention:'30 days',deleted:false,offline:false,error:'',menu:false,variant:'',modal:null,events:[]};}
let state=fresh(),screen='W01',pending;
function route(id){const s=REGISTRY.find(x=>x.id===id);return (s?.route||'/').replace(':caseId',state.caseId).replace(':providerId',state.provider);}
function go(id){state.error='';location.hash=route(id);if(resolve()===screen)render();}
function resolve(){const path=location.hash.slice(1)||'/';return REGISTRY.find(s=>new RegExp('^'+s.route.replace(':caseId','[^/]+').replace(':providerId','[^/]+')+'$').test(path))?.id||'404';}
function log(type){state.events.push({type,time:new Date().toLocaleTimeString()});}
function loadScenario(id,fast=false){clearTimeout(pending);state={...fresh(),scenario:id};state.concern=SCENARIOS.find(s=>s.id===id).concern;if(id==='nomatch')state.criteria.plan='Demo Exclusive Plan',state.criteria.required=true;if(fast){state.consent=true;state.answers=['One to four weeks ago','About the same','4','After long screen sessions','No changes yet.','One to four hours','No additional details.','Yes','Understanding my concern','Yes, ready to review'];state.question=10;state.reviewed=true;state.guidance=true;}log('scenario_loaded');}
function prime(id,variant=''){loadScenario(id==='A15'?'urgent':'routine',true);state.variant=variant;if(id==='A01')state.consent=false;if(id==='A04')state.record=true;if(id==='A05')state.question=1,state.answers=['One to four weeks ago'];if(id==='A13')state.mode='saved';if(id==='A07'&&variant==='loading')state.generating=true,state.guidance=false;if(variant==='error')state.failed=true,state.guidance=false;if(variant==='empty')state.criteria.plan='Demo Exclusive Plan',state.criteria.required=true;if(variant==='offline')state.offline=true;if(variant==='validation')state.error='Choose an answer, select Not sure, or skip this question.';if(variant==='delete')state.modal='delete';if(variant==='contact')state.modal='contact';if(variant==='stale')state.guidance=false,state.variant='stale';location.hash=route(id);screen=id;render();}
function head(title,sub,eye=''){return `<div class="pagehead">${eye?`<div class="eyebrow">${eye}</div>`:''}<h1 tabindex="-1">${title}</h1>${sub?`<p>${sub}</p>`:''}</div>`;}
function shell(content){const pub=screen[0]==='W',ops=screen[0]==='O';const nav=`<div class="demo"><b>INTERACTIVE DEMO</b> &nbsp; · &nbsp; Fictional data &nbsp; · &nbsp; No live AI or medical assessment</div><header class="nav">${L('<span class="logo">+</span>HealthGuide','W01','brand')}<button class="mobilemenu" data-action="menu" aria-label="Toggle navigation" aria-expanded="${state.menu}">Menu</button><nav class="navlinks ${state.menu?'menuopen':''}" aria-label="Main navigation">${L('How it works','W02',screen==='W02'?'active':'')}${L('For healthcare','W03',screen==='W03'?'active':'')}${L('Privacy','W04')}${L('Help','W05')}${L(pub?'Try the demo':'Demo scenarios',pub?'A01':'O03','btn sm')}</nav></header>`;const sidebar=`<aside class="sidebar"><div class="sidelabel labelcaps" style="padding:0 13px 13px">${ops?'Demo studio':'Your workspace'}</div>${(ops?[['O01','◈','Runtime overview'],['O02','◇','Evidence & controls'],['O03','▦','Demo scenarios'],['W01','↗','Patient experience']]:[['A03','+','New consultation'],['A13','◷','History'],['A14','◇','Data settings'],['W05','?','Help']]).map(([id,ico,title])=>id==='A03'?`<a href="#${route(id)}" data-action="newcase" class="${screen===id?'current':''}"><span>${ico}</span>${title}</a>`:L(`<span>${ico}</span>${title}`,id,screen===id?'current':'')).join('')}<div class="sidefoot"><div class="card tinted"><div class="labelcaps">${ops?'Mock adapter':'Fictional profile'}</div><h3 style="margin:8px 0">${ops?'ZGX not connected':'Jordan Taylor'}</h3><p class="small">${ops?'All device figures are illustrative.':'Nothing is saved after a page refresh.'}</p></div>${L(ops?'Back to website':'Open demo studio',ops?'W01':'O03')}</div></aside>`;const foot=`<footer class="footer"><span>HealthGuide · HP ZGX demonstration concept</span><span>Mock mode only · Not for real health decisions</span></footer>`;const toolbar=`<div class="toolbar no-print"><b>DESIGN REFERENCE</b><label>Screen <select id="atlas" aria-label="Open screen mockup">${REGISTRY.map(s=>`<option value="${s.id}" ${s.id===screen?'selected':''}>${s.id} · ${s.title}</option>`).join('')}</select></label><button data-action="reset">Reset demo</button><span>Screen selector seeds a preview state. Normal buttons follow the user journey.</span></div>`;return nav+(pub||screen==='404'?`<main class="page">${content}</main>`:`<div class="layout">${sidebar}<main class="work"><div class="crumb"><span>${ops?'Demo studio':`Consultation / ${SCENARIOS.find(s=>s.id===state.scenario).title}`}</span><span class="screenid">${screen} · ${ops?'Simulated controls':state.mode==='saved'?'Demo saved mode':'Guest demo'}</span></div>${content}</main></div>`)+foot+(CAPTURE?'':toolbar);}
function steps(n){return `<div class="steps" aria-label="Consultation progress">${['Start','Context','Questions','Guidance','Care options'].map((s,i)=>`<div class="step ${i<n?'done':i===n?'current':''}">${i+1}. ${s}</div>`).join('')}</div>`;}
function scenarioCards(){return `<div class="grid2">${SCENARIOS.map((s,i)=>`<article class="card stack">${badge(s.tag,s.tone)}<div><h2>${s.title}</h2><p>${s.desc}</p></div>${B('Explore this scenario →','scenario:'+s.id,'secondary')}</article>`).join('')}</div>`;}
function providerCard(p){return `<article class="card provider"><div class="row between"><div class="detail"><div class="avatar">${p.initials}</div><div><h3>${p.name}</h3><p>${p.specialty} · ${p.practice}</p></div></div>${badge('Fictional doctor','gray')}</div><div class="row">${badge('Relevant specialty','blue')}${badge(p.plan?'Sample plan match':'Plan unknown',p.plan?'':'amber')}${p.tele?badge('Telehealth option','blue'):''}</div><p>${p.distance} miles · ${p.lang} · Availability not connected</p><div class="notice">${p.why}</div><div class="row between"><span class="small muted">Synthetic directory v1 · No real appointment</span>${B('View doctor →','provider:'+p.id,'secondary sm')}</div></article>`;}
function providerRows(){return PROVIDERS.map((p,i)=>({...p,distance:(state.criteria.city==='Irving, TX'?[6.2,3.1,1.8]:[2.4,4.8,7.2])[i]}));}
function matches(){return providerRows().filter(p=>(!state.criteria.required||p.plan===state.criteria.plan)&&p.distance<=parseInt(state.criteria.radius)&&(state.criteria.visit!=='Telehealth only'||p.tele)&&(state.criteria.language!=='Spanish required'||p.lang.includes('Spanish'))).sort((a,b)=>Number(b.plan===state.criteria.plan)-Number(a.plan===state.criteria.plan)||a.distance-b.distance||a.id.localeCompare(b.id));}
function content(){switch(screen){
case 'W01':return `<section class="hero"><div><div class="eyebrow">A clearer path to care</div><h1>Your concern.<br>Your context.<br><span>Your next step.</span></h1><p>Explore a guided health conversation that turns your questions into clear next steps and suitable care options.</p><div class="row">${L('Try a sample consultation →','A01','btn')}${L('See how it works','W02','btn secondary')}</div><p class="small">No account needed. Use fictional examples throughout.</p></div><div class="heroart"><div class="mini">${feature('01','Tell your story','A concern, a little context, and optional records.')}</div><div class="mini">${feature('02','Answer what matters','Up to 10 questions, tailored to the demo pathway.')}</div><div class="mini">${feature('03','Make your next move','Understand guidance. Compare care. Prepare a summary.')}</div></div></section><div class="ribbon"><div><b>Up to 10 questions</b><div class="statlabel">Focused, one at a time</div></div><div><b>Explained next steps</b><div class="statlabel">Context and uncertainty visible</div></div><div><b>Care that fits</b><div class="statlabel">Specialty, distance and preferences</div></div><div><b>Designed for local AI</b><div class="statlabel">Future deployment on one HP ZGX</div></div></div><div class="grid3 mt"><div class="card">${feature('↗','For patients','Less confusion about where to go next.')}</div><div class="card">${feature('◇','For care teams','Better prepared conversations and intake.')}</div><div class="card">${feature('◈','For healthcare leaders','A practical view of local AI workflows.')}</div></div>`;
case 'W02':return head('A little context. A clearer next step.','A guided experience you can explore in a few minutes.','How it works')+`<div class="grid3"><div class="card"><div class="number">01</div><h2 class="mt">Describe the concern</h2><p>Choose a fictional scenario, review Jordan’s profile and optionally attach a sample record.</p></div><div class="card"><div class="number">02</div><h2 class="mt">Answer relevant questions</h2><p>Explore open answers, choices and a scale. You can skip or say you are not sure.</p></div><div class="card"><div class="number">03</div><h2 class="mt">Explore the next step</h2><p>Review illustrative guidance, compare fictional doctors and create a visit summary.</p></div></div><div class="split mt"><div class="card tinted"><div class="eyebrow">A thoughtful conversation</div><h2>“Has the pattern changed?”</h2><div class="row mt">${badge('Improving','blue')}${badge('About the same','blue')}${badge('Worsening','blue')}${badge('Not sure','gray')}</div><p class="mt">Each answer becomes part of a reviewable summary. An urgent scenario interrupts this flow.</p></div><div class="card"><h2>You stay in control</h2><ul class="bullets"><li>Review facts before continuing</li><li>See what is unknown</li><li>Change preferences explicitly</li><li>Reset the entire demo at any time</li></ul>${L('Start exploring →','A01','btn mt')}</div></div>`;
case 'W03':return head('Better navigation. More useful care capacity.','Explore the potential value for patients, care teams, health systems and insurers.','For healthcare CIOs and CTOs')+`<div class="grid3"><div class="card tinted"><div class="icon">↗</div><h2 class="mt">Appropriate first destination</h2><p>Relevant specialty matching may reduce misdirected visits and referral rework.</p><div class="divider"></div><p class="small"><b>Measure:</b> appropriate-first-destination rate.</p></div><div class="card purple"><div class="icon">◷</div><h2 class="mt">Less avoidable workload</h2><p>Suitable guidance and prepared summaries may reduce unnecessary visits and repeated intake.</p><div class="divider"></div><p class="small"><b>Measure:</b> net clinical minutes per episode.</p></div><div class="card peach"><div class="icon">◇</div><h2 class="mt">Lower avoidable spending</h2><p>Better navigation may reduce total episode cost for insurers and risk-bearing providers.</p><div class="divider"></div><p class="small"><b>Measure:</b> adjusted episode cost and quality.</p></div></div><div class="split mt"><div class="card dark"><div class="eyebrow">The technical story</div><h2>One local HP ZGX. An observable workflow.</h2><p>Planned architecture keeps inference, records and case state on the device, with controlled public retrieval.</p><p class="mt small">This browser demo uses bundled fixtures. No device or live model is connected.</p>${L('Explore the demo studio →','O01','btn mt')}</div><div class="card"><h2>Outcomes need evidence</h2>${datum('Avoided visits','Not measured')}${datum('Insurer savings','Not measured')}${datum('Clinical time recovered','Not measured')}<p class="small mt">The demo shows interactions. A real pilot must measure safety, quality, access and cost together.</p></div></div>`;
case 'W04':return head('Your data should have clear boundaries.','Here is exactly what happens in this interactive demonstration.','Privacy and control')+`<div class="split"><div class="card stack">${feature('01','Fictional examples only','Use sample concerns, profiles, records and doctors. Do not enter personal health information.')}${feature('02','Temporary browser memory','Demo choices live in this tab only. Refreshing or resetting clears your progress. No account or backend is used.')}${feature('03','No real upload or model call','The record picker selects bundled examples. Guidance comes from fixed scenario fixtures, not medical analysis.')}${feature('04','Exports are your responsibility','The summary can be printed or saved as PDF. Reset cannot delete a file you downloaded.')}</div><div class="stack"><div class="card tinted"><h2>Planned ZGX deployment</h2><p>The product document describes local inference, authorization, retention and deletion controls. Those production controls are not demonstrated by a static browser mockup.</p></div><div class="card"><h2>Try the controls</h2><p>See the simulated data settings and deletion confirmation.</p>${L('Review data controls →','A14','btn mt')}</div></div></div>`;
case 'W05':return head('A little help, whenever you need it.','Answers about the demo and its boundaries.','Help center')+`<div class="split"><div class="card">${[['Is this giving me medical advice?','No. All outcomes are scripted examples for a product demonstration. The demo does not assess your symptoms.'],['Do I need an account?','No. Guest mode is open to everyone. Saved mode is a simulation within the current tab.'],['Can I upload my own record?','No. Choose one of the sample files on the Records screen. No real file is read or transmitted.'],['Are these real doctors?','No. Every doctor and practice is fictional. Contact actions open a simulation dialog; no appointment is booked.'],['Why does progress disappear after refresh?','The reference intentionally uses memory only. Refresh starts a clean demo session.'],['How can I see every screen?','Use the Design Reference selector below the page, or choose a scenario in the demo studio.']].map(([q,a],i)=>`<details ${i===0?'open':''}><summary>${q}</summary><p>${a}</p></details>`).join('')}</div><div class="stack"><div class="card peach"><h2>Need urgent help in real life?</h2><p>This demo cannot assess or respond to an emergency. Use local emergency services if you need immediate help.</p>${B('View urgent screen','urgent','secondary mt')}</div><div class="card"><h2>Continue exploring</h2>${L('Back to the consultation →',state.consent?'A03':'A01','btn mt')}</div></div></div>`;
case 'A01':return `<div class="narrow">${steps(0)}${head('Let’s explore your next step.','Start with a fictional patient. No account or personal details required.')}<div class="card"><h2>Choose your demo mode</h2><div class="grid2 mt"><label class="choice"><input type="radio" name="mode" value="guest" ${state.mode==='guest'?'checked':''}><span><b>Guest demo</b><small>Quick and temporary</small></span></label><label class="choice"><input type="radio" name="mode" value="saved" ${state.mode==='saved'?'checked':''}><span><b>Saved-mode demo</b><small>Try history in this tab</small></span></label></div><div class="divider"></div><label class="check"><input id="adult" type="checkbox"><span>This fictional patient is 18 or older.</span></label><label class="check"><input id="consent" type="checkbox"><span>I understand this is a mock demonstration, not medical advice, and will use fictional details only.</span></label>${state.error?`<p class="err" role="alert">${state.error}</p>`:''}<div class="actions">${B('Not eligible / decline','decline','ghost')}${B('Accept and begin →','consent')}</div></div><p class="small muted mt">Current scenario: ${SCENARIOS.find(s=>s.id===state.scenario).title}. ${L('Change scenario','O03')}</p></div>`;
case 'A02':return `${steps(1)}${head('A little context about Jordan.','Review the fictional profile or skip this optional step.')}<div class="split"><div class="card"><div class="row between mb"><h2>Health profile</h2>${badge('Fictional patient','blue')}</div><div class="grid2"><label class="field">Fictional name<input value="Jordan Taylor" readonly><span class="hint">Fixed demo identity</span></label>${field('Age','age',state.profile.age,'number')}</div>${field('Medications','medications',state.profile.medications,'text','“Not reported” is different from no medications.')}${sel('Allergies','allergies',['Unknown','None reported','Example allergy'],state.profile.allergies)}${state.error?notice(state.error,'error'):''}<div class="actions">${B('Skip profile','skipprofile','ghost')}${B('Use this profile →','profile')}</div></div><aside class="card tinted"><div class="avatar">JT</div><h2 class="mt">Jordan Taylor</h2><p>38-year-old fictional patient based in Dallas, Texas.</p><div class="divider"></div><p class="small">Saved-mode choices exist only until this page is refreshed. Unknown facts remain visibly unknown.</p></aside></div>`;
case 'A03':return `${steps(1)}${head('What would you like to explore?','Describe one concern using the fictional example below.')}<div class="split"><div class="card"><label class="field">Main concern<textarea id="concern" maxlength="4000">${E(state.concern)}</textarea><span class="hint">You can edit the example text. The selected scenario determines the scripted result.</span></label><div class="row mb">${badge('Jordan Taylor','gray')}${badge('Demo case','blue')}</div>${state.error?notice(state.error,'error'):''}<div class="actions">${L('Back','A02','btn ghost')}${B('Continue →','concern')}</div></div><aside class="stack"><div class="card tinted"><h2>Helpful context</h2><ul class="bullets"><li>When the concern began</li><li>How it affects daily activities</li><li>What the patient wants to understand</li></ul></div><div class="notice warn">This demo does not analyze free text for urgency. ${B('Explore urgent scenario','urgent','ghost sm')}</div></aside></div>`;
case 'A04':return `${steps(1)}${head('Bring the context together.','Add a sample record, then review what was extracted. This step is optional.')}<div class="split"><div class="stack"><div class="card" style="border-style:dashed"><div class="row"><span class="icon">▤</span><div><h2>Choose a sample record</h2><p class="small">No real file upload. A bundled fictional document is used.</p></div></div><div class="row mt">${B('Add sample PDF','record','secondary')}${B('Try unreadable file','badrecord','ghost')}</div></div>${state.record?`<div class="card"><div class="row between"><h3>Jordan_sample_record.pdf</h3>${badge('Sample extraction','blue')}</div><p class="small muted">Fictional source · Page 1 · No OCR is running</p><div class="divider"></div><h3>Review extracted fact</h3><p>${E(state.factText)}</p><div class="row mt">${badge(state.fact==='pending'?'Needs confirmation':state.fact,state.fact==='rejected'?'amber':'')}${B('Confirm','confirmfact','secondary sm')}${B('Correct','correctfact','ghost sm')}${B('Reject','rejectfact','ghost sm')}</div></div>`:''}${state.error?notice(state.error,'error'):''}<div class="actions">${B('Skip records','skiprecords','ghost')}${B('Continue to questions →','recordsnext')}</div></div><aside class="card tinted"><h2>You verify the facts.</h2><p>Nothing from a record is treated as confirmed until you review it.</p><div class="divider"></div><p class="small">Planned product limits: PDF, PNG or JPEG; up to 3 files, 10 MiB each and 30 parsed pages total. The mock only exercises sample states.</p></aside></div>`;
case 'A05':{const q=QUESTIONS[Math.min(state.question,9)],v=state.answers[state.question];return `${steps(2)}<div class="split"><div class="card"><div class="row between mb"><span class="eyebrow" style="margin:0">A focused conversation</span>${badge(`Question ${Math.min(state.question+1,10)} of up to 10`,'blue')}</div><div class="progress mb"><i style="width:${(state.question+1)*10}%"></i></div><h1 style="font-size:29px">${q.text}</h1><p class="mt mb">Answer for Jordan, the fictional patient.</p><div class="stack gap8">${q.type==='single'?q.choices.map(o=>`<label class="choice"><input type="radio" name="answer" value="${E(o)}" ${v===o?'checked':''}><span>${o}</span></label>`).join(''):q.type==='multi'?q.choices.map(o=>`<label class="choice"><input type="checkbox" name="answer" value="${E(o)}"><span>${o}</span></label>`).join(''):q.type==='scale'?`<label class="field">Impact from 0 to 10<input id="scale" type="range" min="0" max="10" value="4" oninput="document.querySelector('#scalevalue').textContent=this.value"><span class="row between"><span class="hint">0 · No impact</span><b id="scalevalue">4</b><span class="hint">10 · Highest impact</span></span></label>`:`<label class="field">Your example answer<textarea id="openanswer" maxlength="2000" placeholder="Use fictional details only">${E(v||'')}</textarea></label>`}</div><details><summary>Why are you asking?</summary><p>${q.why}</p></details>${state.error?`<p class="err" role="alert">${state.error}</p>`:''}<div class="actions">${B('Skip / not sure','skipquestion','ghost')}${B('Submit answer →','answer')}</div></div><aside class="stack"><div class="card tinted"><h3>The story so far</h3>${datum('Patient','Jordan Taylor')}${datum('Answered',String(state.answers.length))}${datum('Main concern','Sample concern')}<p class="small mt">Previous answers stay available on the review screen. You can correct them before generating guidance.</p></div><div class="card"><h3>Explore a safety interruption</h3><p class="small">A preset urgent signal stops the routine pathway.</p>${B('Simulate urgent answer','urgent','secondary mt')}</div></aside></div>`;}
case 'A06':return `${steps(2)}${head('Does this capture the story?','Review the details before creating the sample guidance.')}<div class="split"><div class="stack"><div class="card"><div class="row between"><h2>Main concern</h2>${B('Edit concern','editconcern','ghost sm')}</div><p>${E(state.concern)}</p><div class="divider"></div><h3>Confirmed context</h3>${datum('Age',E(state.profile.age||'Unknown'))}${datum('Medications',E(state.profile.medications))}${datum('Allergies',E(state.profile.allergies))}${datum('Sample record',state.fact==='confirmed'||state.fact==='corrected'?E(state.factText):'No confirmed record facts')}</div><div class="card"><h2>Answers to review</h2>${state.answers.map((a,i)=>`<div class="datum"><div><span class="small muted">${QUESTIONS[i].text}</span><div>${E(a)}</div></div>${B('Edit','editanswer:'+i,'ghost sm')}</div>`).join('')||'<p>No answers yet. Return to the questions.</p>'}</div></div><aside class="stack"><div class="card tinted"><h2>Known limits</h2><p>Allergies and any skipped answers remain unknown. The demo does not verify clinical completeness.</p><label class="check"><input id="review" type="checkbox" ${state.reviewed?'checked':''}><span>I have reviewed these fictional details.</span></label>${state.error?`<p class="err">${state.error}</p>`:''}${B('Generate sample guidance →','generate','mt')}</div><p class="small muted">Editing clinical context invalidates the previous result. The ten-question limit still applies.</p></aside></div>`;
case 'A07':{if(state.generating)return `${steps(3)}${head('Preparing the sample guidance.','Your answers are retained while the demo loads its fixed result.')}<div class="card empty"><div class="spinner"></div><h2 class="mt">Loading the scenario result</h2><p>This is a simulated delay. No AI model is processing your information.</p>${B('Cancel and return to review','cancelgenerate','secondary')}</div>`;if(state.failed)return `${steps(3)}${head('The sample result could not load.','Your fictional answers are still here.')}<div class="card empty"><div class="icon">!</div><h2>Simulated service failure</h2><p>Try again to complete this recovery path. No partial guidance is displayed.</p>${B('Retry sample guidance','retry')}${L('Review answers','A06','btn secondary')}</div>`;if(!state.guidance)return `${steps(3)}${head('Review your updated details.','The previous result is no longer current.')}<div class="card empty"><div class="icon">↻</div><h2>Guidance needs regeneration</h2><p>Return to review and confirm the updated case before creating another result.</p>${L('Review updated case →','A06','btn')}</div>`;const self=state.scenario==='selfcare',limited=state.answers.some(a=>a==='Not sure / skipped');return `${steps(3)}${head('A clearer view of the next step.','A scripted result for Jordan, not an assessment of your health.')}<div class="split"><div class="stack"><div class="card tinted"><div class="row between mb">${badge('Illustrative guidance','blue')}${badge(limited?'Context incomplete':'Demo result',limited?'amber':'')}</div><h2>${limited?'Some context is still missing':self?'Explore a self-care pathway':'A primary care conversation'}</h2><p>${limited?'The demo keeps uncertainty visible and avoids reassuring conclusions. Explore clinician options or revisit skipped answers.':self?'This fictional pathway shows how suitable self-care information could be organized with clear limits and escalation guidance.':'This fictional pathway points to primary care to discuss a recurring concern, review the pattern and decide whether any further evaluation is appropriate.'}</p></div><div class="card"><h2>Prepare for the conversation</h2>${feature('01','Keep the pattern visible','Bring the timing, duration, impact and any changes from the example.')}${feature('02','Bring the relevant context','Use the confirmed sample facts and note the information still unknown.')}${feature('03','Ask about the next step','The summary includes questions the patient can discuss with a clinician.')}</div><div class="notice warn">Possible explanations are not diagnoses. This mock does not determine which explanation is likely or rule anything out.</div></div><aside class="stack"><div class="card"><h2>Continue from here</h2>${L('Find suitable doctors →','A09','btn')}${L('Prepare visit summary','A12','btn secondary mt')}<div class="divider"></div>${L('See evidence layout →','A08')}<p class="small mt">Evidence items are illustrative fixture records, not clinical citations.</p></div><div class="card peach"><h3>If circumstances change</h3><p class="small">The live product would show reviewed escalation guidance here. In this demo, use the urgent scenario to inspect that experience.</p>${B('View urgent example','urgent','ghost sm mt')}</div></aside></div>`;}
case 'A08':return head('See the support behind a statement.','This screen demonstrates traceability using clearly labeled fixture records.')+`<div class="split"><div class="stack">${[['Demo statement 01','A primary care conversation','DEMO-SOURCE-01'],['Demo statement 02','Record the timing and impact','DEMO-SOURCE-02']].map(([t,c,id])=>`<article class="card"><div class="row between mb"><span class="labelcaps">${t}</span>${badge('Illustrative source','amber')}</div><h2>${c}</h2><p>This is the source-card layout. No external clinical reference has been attached to this synthetic claim.</p><div class="divider"></div>${datum('Source ID',id)}${datum('Validation','Not clinically reviewed')}${B('Inspect sample evidence','source:'+id,'secondary mt')}</article>`).join('')}</div><aside class="card tinted"><h2>Support must be specific.</h2><p>The planned product links each material statement to a reviewed source and passage. A URL alone does not establish support.</p>${L('Back to guidance →','A07','btn mt')}</aside></div>`;
case 'A09':return `${steps(4)}${head('Care options that fit your preferences.','Filter a fictional directory. Your selections change the results.')}<div class="split"><div class="card"><div class="grid2">${sel('Location','city',['Dallas, TX','Irving, TX'],state.criteria.city)}${sel('Maximum distance','radius',['5 miles','10 miles','25 miles'],state.criteria.radius)}</div>${sel('Insurance plan','plan',['Demo Health PPO','Demo Exclusive Plan','No plan preference'],state.criteria.plan)}<label class="check mb"><input id="required" type="checkbox" ${state.criteria.required?'checked':''}><span>Require confirmed plan participation in the sample dataset</span></label><div class="grid2">${sel('Visit type','visit',['Any visit type','Telehealth only'],state.criteria.visit)}${sel('Language','language',['Any language','Spanish required'],state.criteria.language)}</div><div class="actions">${L('Back','A07','btn ghost')}${B('Find matches →','search')}</div></div><aside class="card tinted"><h2>What matters most?</h2><p>Required filters exclude unknowns. Optional preferences influence the order without inventing a match score.</p><div class="divider"></div>${datum('Recommended specialty','Primary care')}${datum('Directory','3 fictional providers')}<p class="small mt">Demo city choice changes the sample distance table. None of these records represent real practices.</p></aside></div>`;
case 'A10':{const m=matches();return `${steps(4)}${head(m.length?'Suitable options for your next step.':'No doctors match these requirements.',`${m.length} fictional matches · ${state.criteria.city} · ${state.criteria.radius}`)}${state.offline?notice('Simulated offline mode. Showing bundled directory snapshot v1. No live availability is available.','warn')+'<div class="mt"></div>':''}<div class="split"><div class="stack">${m.length?m.map(providerCard).join(''):`<div class="card empty"><div class="icon">⌕</div><h2>Your required filters excluded every result.</h2><p>The demo will not silently relax insurance, language or distance requirements.</p>${L('Change preferences →','A09','btn')}${B('Remove required insurance filter','relax','secondary mt')}</div>`}</div><aside class="card"><h2>Your preferences</h2>${datum('Specialty','Primary care')}${datum('Plan',E(state.criteria.plan))}${datum('Plan required',state.criteria.required?'Yes':'No')}${datum('Visit',state.criteria.visit)}${L('Edit preferences','A09','btn secondary mt')}<div class="divider"></div><p class="small">Order: specialty fit, preferred plan, distance, stable provider ID. All practice details are synthetic.</p></aside></div>`;}
case 'A11':{const p=providerRows().find(x=>x.id===state.provider)||providerRows()[0];return `${head('A closer look at this care option.','Fictional provider profile. No real contact details or booking.')}<div class="split"><div class="stack"><div class="card"><div class="row"><div class="avatar" style="height:74px;width:74px;font-size:26px">${p.initials}</div><div>${badge('Fictional doctor','gray')}<h1 style="font-size:29px;margin:10px 0 5px">${p.name}</h1><p>${p.specialty} · ${p.practice}</p></div></div><div class="divider"></div><h2>Why this option appears</h2>${datum('Specialty','Primary care matches sample guidance')}${datum('Plan',p.plan||'Unknown in sample data')}${datum('Visit options',p.tele?'In person and telehealth':'In person')}${datum('Distance',p.distance+' miles, simulated')}${datum('Language',p.lang)}</div><div class="card tinted"><h3>What still needs confirmation</h3><p>Real-world credentials, availability, fees and plan participation are not connected in this demo.</p></div></div><aside class="card"><h2>Explore the handoff</h2><p>See the confirmation users would receive before leaving for a provider’s website.</p>${B('Preview contact handoff →','contact','mt')}${L('Prepare visit summary','A12','btn secondary mt')}<div class="divider"></div>${L('← Back to matches','A10')}</aside></div>`;}
case 'A12':return head('A useful summary for the next conversation.','Review the fictional information before printing or saving a PDF.')+`<div class="split"><article class="paper" id="summarypaper"><div class="row between"><div class="brand"><span class="logo">+</span>HealthGuide</div>${badge('SAMPLE ONLY','amber')}</div><h2 class="mt">Appointment preparation summary</h2><p class="small">Jordan Taylor · Case ${state.caseId} · Revision ${state.revision}</p><h3>Reported concern</h3><p>${E(state.concern)}</p><h3>Confirmed context</h3><p>Age: ${E(state.profile.age||'Unknown')}. Medications: ${E(state.profile.medications)}. Allergies: ${E(state.profile.allergies)}.</p><h3>Answers and uncertainties</h3><p>${state.answers.length} responses recorded. ${state.answers.filter(x=>x==='Not sure / skipped').length} skipped or unknown answers. Record fact: ${state.fact==='confirmed'||state.fact==='corrected'?E(state.factText):'None confirmed'}.</p><h3>Questions to discuss</h3><ul class="bullets"><li>What additional context would be useful?</li><li>What would the next appropriate step be?</li><li>What changes should prompt another contact?</li></ul><div class="divider"></div><p class="small">Fixed demonstration content. No medical assessment, diagnosis or clinical source verification. Do not use for real care.</p></article><aside class="card print-hide"><h2>Ready to export?</h2><label class="check"><input id="exportreview" type="checkbox"><span>I have reviewed this fictional summary.</span></label>${state.error?`<p class="err">${state.error}</p>`:''}${B('Print / save as PDF','export','mt')}<p class="small mt">Opens the browser print dialog. Choose “Save as PDF” if available. The downloaded file is outside demo deletion.</p><div class="divider"></div>${B('Save to demo history','savehistory','secondary')}${L('Back to guidance','A07','btn ghost mt')}</aside></div>`;
case 'A13':return head('Your demo consultation history.','Saved-mode examples exist only within this tab. Refresh clears changes.')+`<div class="row mb">${badge(state.mode==='saved'?'Saved mode simulation':'Guest mode','blue')}${state.mode==='guest'?B('Try saved mode','savedmode','secondary sm'):''}</div>${state.mode!=='saved'?`<div class="card empty"><div class="icon">◷</div><h2>Try the saved-history experience.</h2><p>No real sign-in is needed. Switch to the demo saved mode to explore resumable examples.</p>${B('Enter demo saved mode','savedmode')}</div>`:state.history.length?`<div class="stack">${state.history.map(c=>`<div class="card row between"><div><div class="row mb" style="margin-bottom:6px"><h2>${E(c.title)}</h2>${badge('Fictional','gray')}</div><p class="small">${c.date} · ${c.id} · Ready to review</p></div><div class="row">${B('Resume','resume:'+c.id,'secondary')}${B('Delete','deletecase:'+c.id,'ghost')}</div></div>`).join('')}</div>`:`<div class="card empty"><div class="icon">◷</div><h2>No saved demo consultations.</h2><p>Start a sample consultation to explore the full flow again.</p>${L('Start consultation','A01','btn')}</div>`}`;
case 'A14':return head('Your choices. Your demo data.','Explore retention and deletion controls without using personal information.')+`<div class="split"><div class="stack"><div class="card"><h2>Data in this tab</h2>${datum('Profile',state.deleted?'Cleared':'Jordan Taylor · fictional')}${datum('Saved examples',String(state.history.length))}${datum('Storage','Temporary memory only')}<p class="small mt">Reset or refresh clears your changes. Production storage controls described in the master document are not active here.</p></div><div class="card"><h2>Retention preference</h2>${sel('Simulated saved-data retention','retention',['7 days','30 days'],state.retention)}${B('Apply demo preference','retention','secondary')}<p class="small mt">This changes the displayed setting only. There is no background retention service.</p></div></div><aside class="card peach"><h2>Clear this demo session</h2><p>Remove the fictional profile, current consultation, answers and saved examples from this tab.</p>${B('Delete all demo data','delete','danger mt')}<div class="divider"></div><p class="small">Files already printed or downloaded remain on your device.</p></aside></div>`;
case 'A15':return `<div class="narrow">${head('This example needs urgent action.','The urgent scenario stops routine guidance and doctor matching.','Urgent pathway demonstration')}<div class="card" style="border:2px solid #C9806F"><div class="row mb">${badge('Routine flow interrupted','red')}${badge('Scripted example','gray')}</div><h2>Do not continue the routine intake.</h2><p>This is a fictional urgent-signal screen. In a real emergency, contact local emergency services. The demo cannot assess symptoms or dispatch help.</p><div class="notice error mt">US emergency number: <b>911</b>. The button below only simulates the contact action.</div>${B('Preview emergency contact','emergency','danger mt')}<div class="divider"></div><p class="small">No diagnosis, routine result or provider ranking is shown for this urgent case.</p>${B('Start a different demo','choose','secondary mt')}</div></div>`;
case 'A16':return `<div class="narrow">${head('This case needs another path.','The selected example is outside the supported demo experience.')}<div class="card empty"><div class="icon">↗</div><h2>We cannot provide a result for this example.</h2><p>Unsupported scope or declined eligibility leads here. The demo does not invent an answer. A real service would provide a reviewed alternative pathway.</p>${L('Review help and limitations','W05','btn secondary')}${B('Choose another scenario →','choose','mt')}</div></div>`;
case 'O01':return head('A transparent view of the runtime.','Illustrative infrastructure cards for the future local deployment.','Demo studio')+`<div class="notice warn mb">Mock mode: no HP ZGX, ZRT endpoint or model is connected. Metrics below describe the demonstration, not device performance.</div><div class="grid3"><div class="card"><span class="labelcaps">Execution mode</span><div class="metric mt">Browser mock</div><p class="small">Bundled deterministic fixtures</p></div><div class="card"><span class="labelcaps">Local model</span><div class="metric mt">Not connected</div><p class="small">No inference requests</p></div><div class="card"><span class="labelcaps">Clinical outcomes</span><div class="metric mt">Not measured</div><p class="small">A pilot is required</p></div></div><div class="split mt"><div class="card"><h2>Planned local service boundary</h2>${datum('Device','One HP ZGX · planned')}${datum('Runtime adapter','ZRT / vLLM · planned')}${datum('Case and record store','Local service · planned')}${datum('Current source','fixtures.json v1')}${datum('Simulated generation delay','900 ms · scripted')}</div><div class="card tinted"><h2>Explore controlled failure</h2><p>Use the failure scenario to see retained answers, an error state and a successful retry.</p>${B('Load failure scenario','scenario:failure','mt')}${L('Inspect evidence and controls','O02','btn secondary mt')}</div></div>`;
case 'O02':return head('Evidence should be visible, not implied.','Inspect what is simulated and what remains unverified.','Demo studio')+`<div class="grid2"><div class="card"><h2>Data provenance</h2>${datum('Patient records','Fictional fixtures')}${datum('Doctor directory','Synthetic v1')}${datum('Clinical sources','Illustrative only')}${datum('Live corpus refresh','Not implemented')}</div><div class="card"><h2>Control status</h2>${datum('Real file upload','Disabled')}${datum('AI inference','Not connected')}${datum('Production authorization','Not implemented')}${datum('Device deletion evidence','Not verified')}</div></div><div class="card mt"><div class="row between mb"><h2>Demo interaction events</h2>${badge('This tab only','blue')}</div><div class="tablewrap"><table><thead><tr><th>Event</th><th>Time</th><th>Meaning</th></tr></thead><tbody>${state.events.length?state.events.slice(-5).reverse().map(x=>`<tr><td>${x.type}</td><td>${x.time}</td><td>Browser interaction only</td></tr>`).join(''):'<tr><td colspan="3">No events yet. Load a scenario to begin.</td></tr>'}</tbody></table></div><p class="small mt">Events do not contain answer text. They are not evidence of avoided visits, savings or real model performance.</p></div><div class="row mt">${B(state.offline?'Turn off simulated offline':'Simulate offline directory','offline','secondary')}${L('Open scenarios →','O03','btn')}</div>`;
case 'O03':return head('Every pathway, ready to explore.','Load a fictional scenario. It resets this tab so each visitor starts with a clean state.','Demo studio')+scenarioCards()+`<div class="ribbon mt"><div><b>Open to everyone</b><p class="small">No sign-in and no real patient information.</p></div>${B('Reset to a fresh demo','reset','secondary')}</div>`;
default:return head('This demo page could not be found.','Use a known screen or start a new sample consultation.')+L('Return home','W01','btn');}}
function modal(){let title='',body='',actions='';const m=state.modal;if(!m)return '';if(m==='delete'){title='Delete all demo data?';body='This clears the fictional profile, answers, current result and history from this tab. It cannot delete a PDF already saved on your device.';actions=B('Cancel','close','secondary')+B('Delete demo data','confirmdelete','danger');}else if(m==='contact'){title='Preview the provider handoff';body='In the connected product, this dialog would show the verified HTTPS destination. This doctor is fictional, so no external site is opened and no appointment is booked.';actions=B('Cancel','close','secondary')+B('Simulate handoff','handoff');}else if(m==='emergency'){title='Emergency contact simulation';body='No call has been placed. For a real emergency in the United States, dial 911 from your phone. This demonstration cannot contact responders.';actions=B('Close simulation','close','danger');}else if(m==='correct'){title='Correct the sample fact';body=`<label class="field">Corrected fictional fact<input id="correctedfact" value="${E(state.factText)}" maxlength="250"></label>`;actions=B('Cancel','close','secondary')+B('Save correction','savefact');}else if(m==='relax'){title='Remove required insurance?';body='This will include providers with unknown plan participation. They remain visibly marked as unknown.';actions=B('Keep requirement','close','secondary')+B('Remove requirement','confirmrelax');}else if(m.startsWith('deletecase:')){title='Delete this saved example?';body='The sample consultation will be removed from this tab’s history.';actions=B('Cancel','close','secondary')+B('Delete example','confirmcase:'+m.split(':')[1],'danger');}else if(m.startsWith('source:')){title='Illustrative source record';body=`${m.split(':')[1]} is a fixture ID used to demonstrate claim-to-source layout. It is not a clinical citation. No source URL or clinical validation is asserted.`;actions=B('Back to evidence','close','secondary');}else{title='Demo action complete';body=E(m);actions=B('Continue exploring','close');}return `<div class="modalshade"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modaltitle"><h2 id="modaltitle">${title}</h2><div class="muted">${body}</div><div class="row mt">${actions}</div></section></div>`;}
let focusReturn='';
function render(){screen=resolve();if(!CAPTURE&&/^\/app\/cases\//.test(location.hash.slice(1))&&location.hash.slice(1).split('/')[3]!==state.caseId){location.hash=route(state.consent?'A13':'A01');return;}if(!CAPTURE&&screen==='A05'&&state.question>=10&&!state.editingAnswer){location.hash=route('A06');return;}if(!CAPTURE&&['A08','A09','A10','A11','A12'].includes(screen)&&!state.guidance&&state.scenario!=='urgent'){location.hash=route(state.consent?'A06':'A01');return;}const protectedIds=['A02','A03','A04','A05','A06','A07','A08','A09','A10','A11','A12'];if(!CAPTURE&&protectedIds.includes(screen)&&!state.consent){location.hash=route('A01');return;}if(state.scenario==='urgent'&&['A07','A08','A09','A10','A11','A12'].includes(screen)&&!CAPTURE){location.hash=route('A15');return;}$('#root').innerHTML=shell(content())+modal();document.title=`${REGISTRY.find(s=>s.id===screen)?.title||'Page not found'} | HealthGuide demo`;if(state.modal){$('header').inert=true;document.querySelectorAll('main,aside,footer,.toolbar').forEach(n=>n.inert=true);setTimeout(()=>$('.modal button')?.focus(),0);}else if(focusReturn){document.querySelector('[data-action="'+focusReturn+'"]')?.focus();focusReturn='';}}
function invalidate(){state.revision++;state.guidance=false;state.reviewed=false;}
function generate(){clearTimeout(pending);state.generating=true;state.failed=false;state.guidance=false;go('A07');pending=setTimeout(()=>{state.generating=false;if(state.scenario==='failure'&&!state.retried)state.failed=true;else state.guidance=true;log(state.failed?'sample_generation_failed':'sample_guidance_loaded');render();},900);}
function act(a){const [key,arg]=a.split(':');state.error='';if(['contact','delete','emergency','correctfact','relax','deletecase','source'].includes(key))focusReturn=a;switch(key){case'menu':state.menu=!state.menu;break;case'scenario':loadScenario(arg);go('A01');return;case'choose':go('O03');return;case'newcase':{const mode=state.mode,history=state.history,consent=state.consent;clearTimeout(pending);state=fresh();state.mode=mode;state.history=history;state.consent=consent;state.caseId='demo-'+String(Date.now()).slice(-6);go(consent?'A03':'A01');return;}case'reset':clearTimeout(pending);state=fresh();go('W01');return;case'consent':if(!$('#adult').checked||!$('#consent').checked){state.error='Confirm adult eligibility and acknowledge the demo scope to continue.';break;}state.mode=$('input[name="mode"]:checked').value;state.consent=true;log('demo_consent_accepted');go('A02');return;case'decline':go('A16');return;case'profile':if(!$('#age').value||Number($('#age').value)<18||Number($('#age').value)>120){state.error='Use a fictional adult age between 18 and 120.';render();return;}state.profile={age:$('#age').value,medications:$('#medications').value||'Unknown',allergies:$('#allergies').value};go('A03');return;case'skipprofile':state.profile={age:'Unknown',medications:'Unknown',allergies:'Unknown'};go('A03');return;case'concern':if(!$('#concern').value.trim()){state.error='Enter a fictional concern or load a sample scenario.';break;}state.concern=$('#concern').value;invalidate();if(state.scenario==='unsupported'){go('A16');return;}if(state.scenario==='urgent'){go('A15');return;}go('A04');return;case'record':state.record=true;state.fact='pending';break;case'badrecord':state.error='The sample file could not be read. Choose the sample PDF or continue without a record.';break;case'confirmfact':state.fact='confirmed';invalidate();break;case'rejectfact':state.fact='rejected';invalidate();break;case'correctfact':state.modal='correct';break;case'savefact':state.factText=$('#correctedfact').value.trim()||'Unknown';state.fact='corrected';state.modal=null;invalidate();break;case'skiprecords':state.record=false;state.fact='rejected';go('A05');return;case'recordsnext':if(state.record&&state.fact==='pending'){state.error='Confirm, correct or reject the extracted fact before continuing.';break;}go('A05');return;case'answer':case'skipquestion':{const q=QUESTIONS[Math.min(state.question,9)];let v=key==='skipquestion'?'Not sure / skipped':q.type==='single'?$('[name="answer"]:checked')?.value:q.type==='multi'?$$('[name="answer"]:checked').map(n=>n.value).join(', '):q.type==='scale'?$('#scale').value:$('#openanswer').value.trim();if(!v){state.error='Choose an answer, enter sample text, or skip this question.';break;}state.answers[state.question]=v;state.question++;invalidate();log('demo_answer_saved');if(state.editingAnswer){state.editingAnswer=false;state.question=state.answers.length;go('A06');return;}if(state.question>=(state.scenario==='selfcare'?4:10)){go('A06');return;}break;}case'editconcern':invalidate();go('A03');return;case'editanswer':state.question=Number(arg);state.editingAnswer=true;invalidate();go('A05');return;case'generate':if(!$('#review').checked){state.error='Review and confirm the fictional details first.';break;}state.reviewed=true;generate();return;case'retry':state.retried=true;generate();return;case'cancelgenerate':clearTimeout(pending);state.generating=false;go('A06');return;case'urgent':clearTimeout(pending);state.scenario='urgent';state.guidance=false;state.generating=false;log('urgent_demo_interrupted');go('A15');return;case'search':state.criteria={city:$('#city').value,radius:$('#radius').value,plan:$('#plan').value,required:$('#required').checked,visit:$('#visit').value,language:$('#language').value};log('demo_provider_search');go('A10');return;case'provider':state.provider=arg;go('A11');return;case'contact':state.modal='contact';break;case'handoff':state.modal='Simulated handoff complete. No external site opened and no appointment booked.';log('demo_handoff_previewed');break;case'emergency':state.modal='emergency';break;case'source':state.modal='source:'+arg;break;case'relax':state.modal='relax';break;case'confirmrelax':state.criteria.required=false;state.modal=null;break;case'export':if(!$('#exportreview').checked){state.error='Confirm that you reviewed the fictional summary before exporting.';break;}log('demo_print_requested');window.print();return;case'savehistory':state.mode='saved';state.history=state.history.filter(c=>c.id!==state.caseId);state.history.unshift({id:state.caseId,title:'Jordan’s sample consultation',date:'This demo session',scenario:state.scenario,snapshot:JSON.parse(JSON.stringify({profile:state.profile,concern:state.concern,answers:state.answers,record:state.record,fact:state.fact,factText:state.factText,revision:state.revision,guidance:state.guidance}))});go('A13');return;case'savedmode':state.mode='saved';break;case'resume':{const saved=state.history.find(x=>x.id===arg),history=state.history;loadScenario(saved.scenario,true);state.mode='saved';state.history=history;state.caseId=arg;if(saved.snapshot)Object.assign(state,saved.snapshot);go('A06');return;}case'deletecase':state.modal='deletecase:'+arg;break;case'confirmcase':state.history=state.history.filter(c=>c.id!==arg);if(state.caseId===arg){state.answers=[];state.guidance=false;state.reviewed=false;}state.modal=null;break;case'delete':state.modal='delete';break;case'confirmdelete':clearTimeout(pending);state={...fresh(),profile:{age:'',medications:'Unknown',allergies:'Unknown'},history:[],deleted:true,concern:''};log('demo_data_cleared');break;case'retention':state.retention=$('#retention').value;state.modal='Demo retention preference updated. The setting is simulated; this tab still resets on refresh.';break;case'offline':state.offline=!state.offline;state.consent=true;state.guidance=true;go('A10');return;case'close':state.modal=null;break;}render();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b){e.preventDefault();act(b.dataset.action);}});document.addEventListener('change',e=>{if(e.target.id==='atlas')prime(e.target.value);});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.modal){state.modal=null;render();}if(e.key==='Tab'&&state.modal){const f=$$('.modal button,.modal input'),first=f[0],last=f.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});window.addEventListener('hashchange',()=>{state.menu=false;render();window.scrollTo(0,0);document.querySelector('main h1')?.focus();});const params=new URLSearchParams(location.search),CAPTURE=params.has('capture');if(CAPTURE){prime(params.get('screen')||'W01',params.get('variant')||'');}else render();
window.DEMO={prime,loadScenario,getState:()=>state,registry:REGISTRY};
